insert into public.finance_settings(setting_key,setting_value,updated_at) values('task_management_v2_go_live_date',to_jsonb('2026-09-17'::text),now()) on conflict(setting_key) do update set setting_value=excluded.setting_value,updated_at=now();

alter table public.tasks add column if not exists assigned_at timestamptz;
alter table public.tasks add column if not exists assigned_by uuid references public.profiles(id);
alter table public.tasks add column if not exists original_due_date date;
alter table public.tasks add column if not exists original_due_time time without time zone;
alter table public.tasks add column if not exists last_reassigned_at timestamptz;
alter table public.tasks add column if not exists last_reassigned_by uuid references public.profiles(id);
alter table public.tasks add column if not exists last_reassignment_reason text;
alter table public.tasks add column if not exists rework_count integer not null default 0;
update public.tasks set assigned_at=coalesce(assigned_at,created_at),assigned_by=coalesce(assigned_by,created_by),original_due_date=coalesce(original_due_date,due_date),original_due_time=coalesce(original_due_time,due_time) where assigned_at is null or original_due_date is null or (original_due_time is null and due_time is not null);

create table if not exists public.finance_workday_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,work_date date not null,started_at timestamptz not null default now(),ended_at timestamptz,start_note text,end_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,work_date));
alter table public.finance_workday_sessions enable row level security;
create table if not exists public.task_comments(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks(id) on delete cascade,author_id uuid not null references public.profiles(id),comment_type text not null default 'Comment',body text not null,created_at timestamptz not null default now(),constraint task_comments_body_check check(length(trim(body))>0));
create index if not exists task_comments_task_created_idx on public.task_comments(task_id,created_at); alter table public.task_comments enable row level security;
create table if not exists public.task_extension_requests(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks(id) on delete cascade,requested_by uuid not null references public.profiles(id),requested_due_date date not null,requested_due_time time without time zone not null,justification text not null,status text not null default 'Pending' check(status in ('Pending','Approved','Rejected','Needs Clarification')),supervisor_note text,decided_by uuid references public.profiles(id),decided_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists task_extension_task_status_idx on public.task_extension_requests(task_id,status,created_at desc); alter table public.task_extension_requests enable row level security;
create table if not exists public.task_activity_events(id bigint generated by default as identity primary key,task_id uuid not null references public.tasks(id) on delete cascade,actor_id uuid references public.profiles(id),event_type text not null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists task_activity_events_task_created_idx on public.task_activity_events(task_id,created_at); alter table public.task_activity_events enable row level security;
create table if not exists public.task_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,task_id uuid references public.tasks(id) on delete cascade,notification_type text not null,title text not null,message text,unique_key text unique,read_at timestamptz,created_at timestamptz not null default now());
create index if not exists task_notifications_user_created_idx on public.task_notifications(user_id,created_at desc); alter table public.task_notifications enable row level security;

create or replace function private.can_access_task(p_task public.tasks) returns boolean language sql stable security definer set search_path='public','private','pg_temp' as $$ select auth.uid()=p_task.owner_id or auth.uid()=p_task.reviewer_id or private.current_role() in ('CFO','Supervisor'); $$;
create or replace function private.create_task_notification(p_user_id uuid,p_task_id uuid,p_type text,p_title text,p_message text,p_unique_key text default null) returns void language plpgsql security definer set search_path='public','private','pg_temp' as $$ begin if p_user_id is null then return; end if; insert into public.task_notifications(user_id,task_id,notification_type,title,message,unique_key) values(p_user_id,p_task_id,p_type,p_title,p_message,p_unique_key) on conflict(unique_key) do nothing; end $$;
create or replace function private.task_activity_notification_trigger() returns trigger language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare v_task public.tasks%rowtype; v_msg text; begin select * into v_task from public.tasks where id=new.task_id; if not found then return new; end if; v_msg:=coalesce(new.details->>'note',new.details->>'reason',new.details->>'justification',''); if new.event_type in ('EXTENSION_REQUESTED','TASK_SUBMITTED_FOR_REVIEW','COMMENT_ADDED','TASK_REASSIGNED','TASK_EDITED') and v_task.reviewer_id is distinct from new.actor_id then perform private.create_task_notification(v_task.reviewer_id,new.task_id,new.event_type,v_task.name,v_msg,null); end if; if new.event_type in ('TASK_APPROVED','TASK_RETURNED_FOR_REWORK','EXTENSION_APPROVED','EXTENSION_REJECTED','EXTENSION_NEEDS_CLARIFICATION','COMMENT_ADDED','TASK_REASSIGNED','TASK_EDITED') and v_task.owner_id is distinct from new.actor_id then perform private.create_task_notification(v_task.owner_id,new.task_id,new.event_type,v_task.name,v_msg,null); end if; return new; end $$;
drop trigger if exists trg_task_activity_notifications on public.task_activity_events; create trigger trg_task_activity_notifications after insert on public.task_activity_events for each row execute function private.task_activity_notification_trigger();

create or replace function public.start_finance_workday(p_note text default null) returns public.finance_workday_sessions language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare v_date date:=(now() at time zone 'Asia/Riyadh')::date; v_row public.finance_workday_sessions; begin if not exists(select 1 from public.profiles where id=auth.uid() and active=true) then raise exception 'Active profile required'; end if; insert into public.finance_workday_sessions(user_id,work_date,start_note) values(auth.uid(),v_date,nullif(trim(coalesce(p_note,'')),'')) on conflict(user_id,work_date) do update set updated_at=now() returning * into v_row; insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'START_WORKDAY','finance_workday_session',v_row.id::text,jsonb_build_object('work_date',v_date)); return v_row; end $$;
revoke all on function public.start_finance_workday(text) from public; grant execute on function public.start_finance_workday(text) to authenticated;
create or replace function public.get_my_workday_status() returns table(work_date date,started_at timestamptz,ended_at timestamptz,is_started boolean) language sql stable security definer set search_path='public','private','pg_temp' as $$ with d as(select (now() at time zone 'Asia/Riyadh')::date work_date) select d.work_date,s.started_at,s.ended_at,(s.id is not null) from d left join public.finance_workday_sessions s on s.user_id=auth.uid() and s.work_date=d.work_date; $$;
grant execute on function public.get_my_workday_status() to authenticated;

create or replace function public.add_task_comment(p_task_id uuid,p_body text,p_comment_type text default 'Comment') returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare v_task public.tasks%rowtype; v_id uuid; v_type text:=coalesce(nullif(trim(p_comment_type),''),'Comment'); begin if nullif(trim(coalesce(p_body,'')),'') is null then raise exception 'Comment is required'; end if; select * into v_task from public.tasks where id=p_task_id; if not found then raise exception 'Task not found'; end if; if not private.can_access_task(v_task) then raise exception 'Not authorized for this task'; end if; insert into public.task_comments(task_id,author_id,comment_type,body) values(p_task_id,auth.uid(),v_type,trim(p_body)) returning id into v_id; insert into public.task_activity_events(task_id,actor_id,event_type,details) values(p_task_id,auth.uid(),'COMMENT_ADDED',jsonb_build_object('comment_id',v_id,'comment_type',v_type)); insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'ADD_TASK_COMMENT','task',p_task_id::text,jsonb_build_object('comment_type',v_type)); return v_id; end $$;
grant execute on function public.add_task_comment(uuid,text,text) to authenticated;

create or replace function public.request_task_extension(p_task_id uuid,p_requested_due_date date,p_requested_due_time time,p_justification text) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare v_task public.tasks%rowtype; v_id uuid; v_requested timestamptz; begin select * into v_task from public.tasks where id=p_task_id for update; if not found then raise exception 'Task not found'; end if; if v_task.owner_id<>auth.uid() then raise exception 'Only task owner can request extension'; end if; if v_task.status in ('مكتمل','بانتظار المراجعة') then raise exception 'Closed/submitted task cannot request extension'; end if; if nullif(trim(coalesce(p_justification,'')),'') is null then raise exception 'Extension justification is required'; end if; v_requested:=private.task_deadline(p_requested_due_date,p_requested_due_time); if v_requested<=now() then raise exception 'Requested deadline must be in the future'; end if; if exists(select 1 from public.task_extension_requests where task_id=p_task_id and status='Pending') then raise exception 'A pending extension request already exists'; end if; insert into public.task_extension_requests(task_id,requested_by,requested_due_date,requested_due_time,justification) values(p_task_id,auth.uid(),p_requested_due_date,p_requested_due_time,trim(p_justification)) returning id into v_id; insert into public.task_activity_events(task_id,actor_id,event_type,details) values(p_task_id,auth.uid(),'EXTENSION_REQUESTED',jsonb_build_object('request_id',v_id,'requested_due_date',p_requested_due_date,'requested_due_time',p_requested_due_time,'justification',trim(p_justification))); insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'REQUEST_TASK_EXTENSION','task',p_task_id::text,jsonb_build_object('request_id',v_id)); return v_id; end $$;
grant execute on function public.request_task_extension(uuid,date,time,text) to authenticated;

create or replace function public.decide_task_extension(p_request_id uuid,p_decision text,p_note text default null,p_due_date date default null,p_due_time time default null) returns void language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare v_req public.task_extension_requests%rowtype; v_task public.tasks%rowtype; v_status text; v_date date; v_time time; begin if private.current_role() not in ('CFO','Supervisor') then raise exception 'Only CFO or Supervisor can decide extension requests'; end if; select * into v_req from public.task_extension_requests where id=p_request_id for update; if not found then raise exception 'Extension request not found'; end if; if v_req.status<>'Pending' then raise exception 'Extension request is already decided'; end if; select * into v_task from public.tasks where id=v_req.task_id for update; if p_decision not in ('Approved','Rejected','Needs Clarification') then raise exception 'Invalid decision'; end if; v_status:=p_decision; if v_status='Approved' then v_date:=coalesce(p_due_date,v_req.requested_due_date); v_time:=coalesce(p_due_time,v_req.requested_due_time); if private.task_deadline(v_date,v_time)<=now() then raise exception 'Approved deadline must be in the future'; end if; update public.tasks set original_due_date=coalesce(original_due_date,due_date),original_due_time=coalesce(original_due_time,due_time),due_date=v_date,due_time=v_time,updated_at=now() where id=v_task.id; end if; update public.task_extension_requests set status=v_status,supervisor_note=nullif(trim(coalesce(p_note,'')),''),decided_by=auth.uid(),decided_at=now(),updated_at=now() where id=p_request_id; insert into public.task_activity_events(task_id,actor_id,event_type,details) values(v_task.id,auth.uid(),'EXTENSION_'||upper(replace(v_status,' ', '_')),jsonb_build_object('request_id',p_request_id,'decision',v_status,'note',nullif(trim(coalesce(p_note,'')),''),'approved_due_date',v_date,'approved_due_time',v_time)); insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'DECIDE_TASK_EXTENSION','task',v_task.id::text,jsonb_build_object('request_id',p_request_id,'decision',v_status)); end $$;
grant execute on function public.decide_task_extension(uuid,text,text,date,time) to authenticated;

create or replace function public.reassign_finance_task(p_task_id uuid,p_new_owner_id uuid,p_reason text) returns void language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare v_task public.tasks%rowtype; v_new_role text; v_reviewer uuid; begin if private.current_role() not in ('CFO','Supervisor') then raise exception 'Only CFO or Supervisor can reassign tasks'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Reassignment reason is required'; end if; select * into v_task from public.tasks where id=p_task_id for update; if not found then raise exception 'Task not found'; end if; if v_task.status='مكتمل' then raise exception 'Completed task cannot be reassigned'; end if; select role into v_new_role from public.profiles where id=p_new_owner_id and active=true; if v_new_role is null then raise exception 'Valid active assignee required'; end if; if v_new_role='Supervisor' then select id into v_reviewer from public.profiles where active=true and role='CFO' order by created_at limit 1; else select id into v_reviewer from public.profiles where active=true and role='Supervisor' order by created_at limit 1; end if; update public.tasks set owner_id=p_new_owner_id,reviewer_id=coalesce(v_reviewer,reviewer_id),assigned_at=now(),assigned_by=auth.uid(),last_reassigned_at=now(),last_reassigned_by=auth.uid(),last_reassignment_reason=trim(p_reason),started_at=null,status=case when status='بانتظار المراجعة' then 'لم يبدأ' else status end,review_requested_at=null,updated_at=now() where id=p_task_id; insert into public.task_activity_events(task_id,actor_id,event_type,details) values(p_task_id,auth.uid(),'TASK_REASSIGNED',jsonb_build_object('old_owner_id',v_task.owner_id,'new_owner_id',p_new_owner_id,'reason',trim(p_reason))); insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'REASSIGN_TASK','task',p_task_id::text,jsonb_build_object('old_owner_id',v_task.owner_id,'new_owner_id',p_new_owner_id,'reason',trim(p_reason))); end $$;
grant execute on function public.reassign_finance_task(uuid,uuid,text) to authenticated;

create or replace function public.update_finance_task_management(p_task_id uuid,p_name text,p_priority text,p_due_date date,p_due_time time,p_reviewer_id uuid default null,p_note text default null) returns void language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare v_task public.tasks%rowtype; begin if private.current_role() not in ('CFO','Supervisor') then raise exception 'Only CFO or Supervisor can edit task management fields'; end if; select * into v_task from public.tasks where id=p_task_id for update; if not found then raise exception 'Task not found'; end if; if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'Task name is required'; end if; if p_due_date is null or p_due_time is null then raise exception 'Due date and due time are required'; end if; update public.tasks set original_due_date=coalesce(original_due_date,due_date),original_due_time=coalesce(original_due_time,due_time),name=trim(p_name),priority=coalesce(nullif(p_priority,''),priority),due_date=p_due_date,due_time=p_due_time,reviewer_id=coalesce(p_reviewer_id,reviewer_id),updated_at=now() where id=p_task_id; insert into public.task_activity_events(task_id,actor_id,event_type,details) values(p_task_id,auth.uid(),'TASK_EDITED',jsonb_build_object('previous_name',v_task.name,'previous_priority',v_task.priority,'previous_due_date',v_task.due_date,'previous_due_time',v_task.due_time,'new_name',trim(p_name),'new_priority',p_priority,'new_due_date',p_due_date,'new_due_time',p_due_time,'note',nullif(trim(coalesce(p_note,'')),''))); insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'EDIT_TASK_MANAGEMENT','task',p_task_id::text,jsonb_build_object('note',nullif(trim(coalesce(p_note,'')),''))); end $$;
grant execute on function public.update_finance_task_management(uuid,text,text,date,time,uuid,text) to authenticated;

create or replace function public.get_task_collaboration(p_task_id uuid) returns jsonb language plpgsql stable security definer set search_path='public','private','pg_temp' as $$ declare v_task public.tasks%rowtype; v_result jsonb; begin select * into v_task from public.tasks where id=p_task_id; if not found then raise exception 'Task not found'; end if; if not private.can_access_task(v_task) then raise exception 'Not authorized for this task'; end if; select jsonb_build_object('comments',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'body',c.body,'comment_type',c.comment_type,'created_at',c.created_at,'author_id',c.author_id,'author_name',p.full_name,'author_role',p.role) order by c.created_at) from public.task_comments c join public.profiles p on p.id=c.author_id where c.task_id=p_task_id),'[]'::jsonb),'extensions',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'requested_by',e.requested_by,'requested_by_name',p.full_name,'requested_due_date',e.requested_due_date,'requested_due_time',e.requested_due_time,'justification',e.justification,'status',e.status,'supervisor_note',e.supervisor_note,'decided_by',e.decided_by,'decided_at',e.decided_at,'created_at',e.created_at) order by e.created_at desc) from public.task_extension_requests e join public.profiles p on p.id=e.requested_by where e.task_id=p_task_id),'[]'::jsonb),'events',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'event_type',a.event_type,'details',a.details,'created_at',a.created_at,'actor_id',a.actor_id,'actor_name',p.full_name) order by a.created_at desc) from public.task_activity_events a left join public.profiles p on p.id=a.actor_id where a.task_id=p_task_id),'[]'::jsonb)) into v_result; return v_result; end $$;
grant execute on function public.get_task_collaboration(uuid) to authenticated;
create or replace function public.get_my_task_notifications(p_limit integer default 50) returns table(id uuid,task_id uuid,notification_type text,title text,message text,read_at timestamptz,created_at timestamptz) language sql stable security definer set search_path='public','private','pg_temp' as $$ select n.id,n.task_id,n.notification_type,n.title,n.message,n.read_at,n.created_at from public.task_notifications n where n.user_id=auth.uid() order by n.created_at desc limit least(greatest(coalesce(p_limit,50),1),200); $$;
grant execute on function public.get_my_task_notifications(integer) to authenticated;
create or replace function public.mark_task_notification_read(p_notification_id uuid) returns void language plpgsql security definer set search_path='public','private','pg_temp' as $$ begin update public.task_notifications set read_at=coalesce(read_at,now()) where id=p_notification_id and user_id=auth.uid(); end $$;
grant execute on function public.mark_task_notification_read(uuid) to authenticated;

create or replace function public.review_finance_task(p_task_id uuid,p_approve boolean,p_note text default null) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_task public.tasks%rowtype; v_role text:=private.current_role(); begin select * into v_task from public.tasks where id=p_task_id for update; if not found then raise exception 'Task not found'; end if; if v_task.status<>'بانتظار المراجعة' then raise exception 'Task is not awaiting review'; end if; if not (auth.uid()=v_task.reviewer_id or v_role='CFO' or (v_role='Supervisor' and v_task.owner_id<>auth.uid())) then raise exception 'Not authorized to review this task'; end if; if p_approve then update public.tasks set status='مكتمل',completed_at=now(),reviewed_at=now(),reviewed_by=auth.uid(),review_note=nullif(trim(coalesce(p_note,'')),''),updated_at=now() where id=p_task_id; else update public.tasks set status='قيد التنفيذ',review_requested_at=null,reviewed_at=now(),reviewed_by=auth.uid(),review_note=nullif(trim(coalesce(p_note,'')),''),completed_at=null,rework_count=coalesce(rework_count,0)+1,updated_at=now() where id=p_task_id; end if; insert into public.task_activity_events(task_id,actor_id,event_type,details) values(p_task_id,auth.uid(),case when p_approve then 'TASK_APPROVED' else 'TASK_RETURNED_FOR_REWORK' end,jsonb_build_object('note',nullif(trim(coalesce(p_note,'')),''))); insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),case when p_approve then 'APPROVE_TASK_REVIEW' else 'RETURN_TASK_REVIEW' end,'task',p_task_id::text,jsonb_build_object('note',nullif(trim(coalesce(p_note,'')),''))); end $$;
create or replace function public.start_finance_task(p_task_id uuid) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_task public.tasks%rowtype; begin select * into v_task from public.tasks where id=p_task_id for update; if not found then raise exception 'Task not found'; end if; if v_task.owner_id<>auth.uid() then raise exception 'Only task owner can start the task'; end if; if v_task.frequency='يومي' and v_task.opened_at is null then raise exception 'Daily task has not been released by the Supervisor'; end if; if v_task.status='مكتمل' then raise exception 'Completed task cannot be restarted'; end if; update public.tasks set status='قيد التنفيذ',started_at=coalesce(started_at,now()),updated_at=now() where id=p_task_id; insert into public.task_activity_events(task_id,actor_id,event_type,details) values(p_task_id,auth.uid(),'TASK_STARTED','{}'); insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'START_TASK','task',p_task_id::text,jsonb_build_object('name',v_task.name)); end $$;
create or replace function public.complete_finance_task(p_task_id uuid,p_justification text default null) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_task public.tasks%rowtype; v_deadline timestamptz; v_requires_justification boolean; v_justification text; begin select * into v_task from public.tasks where id=p_task_id for update; if not found then raise exception 'Task not found'; end if; if v_task.owner_id<>auth.uid() then raise exception 'Only task owner can complete the task'; end if; if v_task.frequency='يومي' and v_task.opened_at is null then raise exception 'Daily task has not been released by the Supervisor'; end if; if nullif(trim(coalesce(v_task.blocker_note,'')),'') is not null then raise exception 'TASK_BLOCKER_MUST_BE_CLEARED'; end if; if v_task.status='بانتظار المراجعة' then raise exception 'Task is already awaiting review'; end if; v_deadline:=private.task_deadline(v_task.due_date,v_task.due_time); v_requires_justification:=(v_deadline is not null and now()>v_deadline) or v_task.justification_requested_at is not null; v_justification:=coalesce(nullif(trim(coalesce(p_justification,'')),''),v_task.delay_justification); if v_requires_justification and v_justification is null then raise exception 'DELAY_JUSTIFICATION_REQUIRED'; end if; update public.tasks set status='بانتظار المراجعة',review_requested_at=now(),reviewed_at=null,reviewed_by=null,review_note=null,delay_justification=case when v_requires_justification then v_justification else delay_justification end,justification_submitted_at=case when v_requires_justification then coalesce(justification_submitted_at,now()) else justification_submitted_at end,updated_at=now() where id=p_task_id; insert into public.task_activity_events(task_id,actor_id,event_type,details) values(p_task_id,auth.uid(),'TASK_SUBMITTED_FOR_REVIEW',jsonb_build_object('deadline',v_deadline,'late',v_deadline is not null and now()>v_deadline)); insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'SUBMIT_TASK_FOR_REVIEW','task',p_task_id::text,jsonb_build_object('deadline',v_deadline,'late',v_deadline is not null and now()>v_deadline,'justification',case when v_requires_justification then v_justification else null end)); end $$;

create or replace function private.task_deadline_monitor_tick() returns integer language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare v_count integer:=0; v_rows integer:=0; v_today date:=(now() at time zone 'Asia/Riyadh')::date; v_go_live date; begin select coalesce((select trim(both '"' from setting_value::text)::date from public.finance_settings where setting_key='task_management_v2_go_live_date'),'2026-09-17'::date) into v_go_live; insert into public.task_notifications(user_id,task_id,notification_type,title,message,unique_key) select t.owner_id,t.id,'DUE_SOON',t.name,'Task is due within 60 minutes','due-soon:'||t.id::text||':'||v_today::text from public.tasks t where t.due_date>=v_go_live and t.status not in ('مكتمل','بانتظار المراجعة') and private.task_deadline(t.due_date,t.due_time)>now() and private.task_deadline(t.due_date,t.due_time)<=now()+interval '60 minutes' on conflict(unique_key) do nothing; get diagnostics v_rows=row_count; v_count:=v_count+v_rows; insert into public.task_notifications(user_id,task_id,notification_type,title,message,unique_key) select t.owner_id,t.id,'OVERDUE',t.name,'Task is overdue','overdue-owner:'||t.id::text||':'||v_today::text from public.tasks t where t.due_date>=v_go_live and t.status not in ('مكتمل','بانتظار المراجعة') and private.task_deadline(t.due_date,t.due_time)<now() on conflict(unique_key) do nothing; get diagnostics v_rows=row_count; v_count:=v_count+v_rows; insert into public.task_notifications(user_id,task_id,notification_type,title,message,unique_key) select t.reviewer_id,t.id,'OVERDUE_ESCALATION',t.name,'Assigned task is more than 60 minutes overdue','overdue-reviewer:'||t.id::text||':'||v_today::text from public.tasks t where t.reviewer_id is not null and t.due_date>=v_go_live and t.status not in ('مكتمل','بانتظار المراجعة') and private.task_deadline(t.due_date,t.due_time)<now()-interval '60 minutes' on conflict(unique_key) do nothing; get diagnostics v_rows=row_count; v_count:=v_count+v_rows; return v_count; end $$;

do $$ declare v_jobid bigint; begin if not exists(select 1 from cron.job where jobname='sanam_task_v2_deadline_monitor') then v_jobid:=cron.schedule('sanam_task_v2_deadline_monitor','0 * * * *','select private.task_deadline_monitor_tick();'); perform cron.alter_job(v_jobid,active=>false); end if; end $$;

create or replace function public.set_finance_automation_state(p_jobname text,p_active boolean,p_reason text default null) returns void language plpgsql security definer set search_path='public','private','cron','pg_temp' as $$ declare v_old boolean; v_jobid bigint; begin if private.current_role()<>'CFO' then raise exception 'Only CFO can change automation state'; end if; if p_jobname not in ('sanam_generate_daily_tasks','sanam_generate_monthly_close_tasks','sanam_task_v2_deadline_monitor') then raise exception 'Unsupported finance automation'; end if; select jobid,active into v_jobid,v_old from cron.job where jobname=p_jobname; if v_jobid is null then raise exception 'Automation job not found'; end if; perform cron.alter_job(v_jobid,active=>p_active); insert into public.audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'SET_AUTOMATION_STATE','cron_job',p_jobname,jsonb_build_object('previous_active',v_old,'new_active',p_active,'reason',nullif(trim(coalesce(p_reason,'')),''))); end $$;
revoke all on function public.set_finance_automation_state(text,boolean,text) from public; grant execute on function public.set_finance_automation_state(text,boolean,text) to authenticated;

create or replace function public.get_automation_health() returns table(system_name text,job_name text,active boolean,schedule text,last_run_at timestamptz,last_status text,next_run_at timestamptz,missing_count integer,detail text) language sql stable security definer set search_path=public,private,cron,pg_temp as $$ with ctx as(select private.current_role() current_role,(now() at time zone 'Asia/Riyadh') local_now,(now() at time zone 'Asia/Riyadh')::date local_date),jobs as(select j.jobid,j.jobname,j.active,j.schedule from cron.job j,ctx c where c.current_role in ('CFO','Supervisor') and j.jobname in ('sanam_generate_daily_tasks','sanam_generate_monthly_close_tasks','sanam_task_v2_deadline_monitor')),latest as(select j.*,r.start_time,r.status,r.return_message from jobs j left join lateral(select d.start_time,d.status,d.return_message from cron.job_run_details d where d.jobid=j.jobid order by d.start_time desc limit 1) r on true),counts as(select (select count(*)::int from private.daily_task_templates where active=true) daily_expected,(select count(*)::int from public.tasks t join private.daily_task_templates d on d.active=true and d.owner_id=t.owner_id and d.name=t.name where t.frequency='يومي' and t.due_date=(select local_date from ctx)) daily_actual,(select count(*)::int from private.monthly_close_templates where active=true) close_expected,(select count(*)::int from public.monthly_close_tasks where close_period=(select max(close_period) from public.monthly_close_tasks)) close_actual) select case l.jobname when 'sanam_generate_daily_tasks' then 'تجديد المهام اليومية' when 'sanam_generate_monthly_close_tasks' then 'تجديد الإقفال الشهري' else 'مراقبة مواعيد المهام والتنبيهات' end,l.jobname,l.active,l.schedule,l.start_time,l.status,case when l.jobname='sanam_generate_daily_tasks' then ((case when (select local_now::time from ctx)<time '00:05' then (select local_date from ctx) else (select local_date+1 from ctx) end)::timestamp+time '00:05') at time zone 'Asia/Riyadh' when l.jobname='sanam_generate_monthly_close_tasks' then (date_trunc('month',(select local_date from ctx)+interval '1 month')::date::timestamp+time '00:10') at time zone 'Asia/Riyadh' else date_trunc('hour',now())+interval '1 hour' end,case when l.jobname='sanam_generate_daily_tasks' then greatest(0,c.daily_expected-c.daily_actual) when l.jobname='sanam_generate_monthly_close_tasks' then greatest(0,c.close_expected-c.close_actual) else 0 end,coalesce(l.return_message,case when l.jobname='sanam_task_v2_deadline_monitor' and l.active=false then 'جاهز — ينتظر تفعيل المدير المالي' when l.start_time is null then 'لم يتم تسجيل تشغيل بعد' else '—' end) from latest l cross join counts c order by l.jobname; $$;
revoke all on function public.get_automation_health() from public; grant execute on function public.get_automation_health() to authenticated;

create or replace function public.get_supervisor_control_center() returns table(user_id uuid,full_name text,role text,current_task text,current_status text,next_due_at timestamptz,remaining_minutes integer,today_total integer,today_completed integer,overdue_count integer,blocker_count integer,pending_review_count integer,pending_justifications integer) language sql stable security definer set search_path=public,private,pg_temp as $$ with ctx as(select (now() at time zone 'Asia/Riyadh')::date today,private.current_role() current_role,coalesce((select trim(both '"' from setting_value::text)::date from public.finance_settings where setting_key='task_management_v2_go_live_date'),'2026-09-17'::date) go_live),people as(select p.id,p.full_name,p.role from public.profiles p,ctx c where p.active=true and p.role in ('Supervisor','BankAccountant','GLAccountant','ARAccountant','APAccountant') and c.current_role in ('CFO','Supervisor')),stats as(select pe.id,count(t.id) filter(where t.due_date=c.today)::int today_total,count(t.id) filter(where t.due_date=c.today and t.status='مكتمل')::int today_completed,count(t.id) filter(where t.due_date>=c.go_live and t.status not in ('مكتمل','بانتظار المراجعة') and private.task_deadline(t.due_date,t.due_time)<now())::int overdue_count,count(t.id) filter(where t.due_date>=c.go_live and nullif(trim(coalesce(t.blocker_note,'')),'') is not null and t.status<>'مكتمل')::int blocker_count,count(t.id) filter(where t.due_date>=c.go_live and t.status='بانتظار المراجعة')::int pending_review_count,count(t.id) filter(where t.due_date>=c.go_live and t.status not in ('مكتمل','بانتظار المراجعة') and ((private.task_deadline(t.due_date,t.due_time)<now()) or t.justification_requested_at is not null) and nullif(trim(coalesce(t.delay_justification,'')),'') is null)::int pending_justifications from people pe cross join ctx c left join public.tasks t on t.owner_id=pe.id group by pe.id),current_one as(select pe.id,t.name,t.status,private.task_deadline(t.due_date,t.due_time) due_at,row_number() over(partition by pe.id order by case when nullif(trim(coalesce(t.blocker_note,'')),'') is not null then 0 when t.status='قيد التنفيذ' then 1 else 2 end,private.task_deadline(t.due_date,t.due_time) nulls last,t.created_at) rn from people pe cross join ctx c left join public.tasks t on t.owner_id=pe.id and t.due_date=c.today and t.due_date>=c.go_live and t.status not in ('مكتمل','بانتظار المراجعة') and (t.frequency<>'يومي' or t.opened_at is not null)) select pe.id,pe.full_name,pe.role,co.name,co.status,co.due_at,case when co.due_at is null then null else floor(extract(epoch from(co.due_at-now()))/60)::int end,s.today_total,s.today_completed,s.overdue_count,s.blocker_count,s.pending_review_count,s.pending_justifications from people pe join stats s on s.id=pe.id left join current_one co on co.id=pe.id and co.rn=1 order by pe.full_name; $$;
grant execute on function public.get_supervisor_control_center() to authenticated;

create or replace function public.get_workload_capacity() returns table(user_id uuid,full_name text,role text,capacity_tasks integer,planned_open integer,critical_open integer,high_open integer,overdue_open integer,pending_review integer,blockers integer,utilization_percent numeric) language sql stable security definer set search_path=public,private,pg_temp as $$ with ctx as(select (now() at time zone 'Asia/Riyadh')::date today,private.current_role() current_role,coalesce((select trim(both '"' from setting_value::text)::date from public.finance_settings where setting_key='task_management_v2_go_live_date'),'2026-09-17'::date) go_live),people as(select p.id,p.full_name,p.role from public.profiles p,ctx c where p.active=true and p.role in ('Supervisor','BankAccountant','GLAccountant','ARAccountant','APAccountant') and c.current_role in ('CFO','Supervisor')),stats as(select pe.id,count(t.id) filter(where t.due_date=c.today and t.status<>'مكتمل')::int planned_open,count(t.id) filter(where t.due_date=c.today and t.status<>'مكتمل' and t.priority='حرج')::int critical_open,count(t.id) filter(where t.due_date=c.today and t.status<>'مكتمل' and t.priority in ('عالي','عاجل'))::int high_open,count(t.id) filter(where t.due_date>=c.go_live and t.status not in ('مكتمل','بانتظار المراجعة') and private.task_deadline(t.due_date,t.due_time)<now())::int overdue_open,count(t.id) filter(where t.due_date>=c.go_live and t.status='بانتظار المراجعة')::int pending_review,count(t.id) filter(where t.due_date>=c.go_live and t.status<>'مكتمل' and nullif(trim(coalesce(t.blocker_note,'')),'') is not null)::int blockers from people pe cross join ctx c left join public.tasks t on t.owner_id=pe.id group by pe.id) select pe.id,pe.full_name,pe.role,cs.capacity_tasks,coalesce(s.planned_open,0),coalesce(s.critical_open,0),coalesce(s.high_open,0),coalesce(s.overdue_open,0),coalesce(s.pending_review,0),coalesce(s.blockers,0),case when cs.capacity_tasks is null or cs.capacity_tasks=0 then null else round(coalesce(s.planned_open,0)*100.0/cs.capacity_tasks,1) end from people pe left join stats s on s.id=pe.id left join public.team_capacity_settings cs on cs.user_id=pe.id order by case pe.role when 'Supervisor' then 1 when 'BankAccountant' then 2 when 'GLAccountant' then 3 when 'ARAccountant' then 4 when 'APAccountant' then 5 else 9 end,pe.full_name; $$;
grant execute on function public.get_workload_capacity() to authenticated;

insert into public.task_activity_events(task_id,actor_id,event_type,details,created_at) select t.id,t.created_by,'TASK_BASELINE_IMPORTED',jsonb_build_object('status',t.status,'due_date',t.due_date,'due_time',t.due_time),coalesce(t.created_at,now()) from public.tasks t where not exists(select 1 from public.task_activity_events a where a.task_id=t.id);